package com.perilousmoonssplits;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Getter;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;

@Getter
public enum MoonsBoss
{
	BLOOD("Blood", NpcID.PMOON_BOSS_BLOOD_MOON_VIS, NpcID.PMOON_BOSS_BLOOD_MOON),
	ECLIPSE("Eclipse", NpcID.PMOON_BOSS_ECLIPSE_MOON_VIS, NpcID.PMOON_BOSS_ECLIPSE_MOON),
	BLUE("Blue", NpcID.PMOON_BOSS_BLUE_MOON_VIS, NpcID.PMOON_BOSS_BLUE_MOON);

	private static final List<List<MoonsBoss>> ALL_ROUTES = Collections.unmodifiableList(Arrays.asList(
		Arrays.asList(BLOOD, ECLIPSE, BLUE),
		Arrays.asList(BLOOD, BLUE, ECLIPSE),
		Arrays.asList(ECLIPSE, BLOOD, BLUE),
		Arrays.asList(ECLIPSE, BLUE, BLOOD),
		Arrays.asList(BLUE, BLOOD, ECLIPSE),
		Arrays.asList(BLUE, ECLIPSE, BLOOD)
	));

	private final String shortName;
	private final int[] npcIds;

	MoonsBoss(String shortName, int... npcIds)
	{
		this.shortName = shortName;
		this.npcIds = npcIds;
	}

	static List<List<MoonsBoss>> allRoutes()
	{
		return ALL_ROUTES;
	}

	static String formatRoute(List<MoonsBoss> route)
	{
		StringBuilder builder = new StringBuilder();
		for (int i = 0; i < route.size(); i++)
		{
			if (i > 0)
			{
				builder.append(" -> ");
			}
			builder.append(route.get(i).shortName);
		}
		return builder.toString();
	}

	static MoonsBoss fromNpcId(int npcId)
	{
		for (MoonsBoss boss : values())
		{
			for (int id : boss.npcIds)
			{
				if (id == npcId)
				{
					return boss;
				}
			}
		}
		return null;
	}

	static MoonsBoss fromDeathVarbit(int varbitId)
	{
		if (varbitId == VarbitID.PMOON_BOSS_BLOOD_DEAD)
		{
			return BLOOD;
		}
		if (varbitId == VarbitID.PMOON_BOSS_BLUE_DEAD)
		{
			return BLUE;
		}
		if (varbitId == VarbitID.PMOON_BOSS_ECLIPSE_DEAD)
		{
			return ECLIPSE;
		}
		return null;
	}
}

package com.perilousmoonssplits;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Region IDs for Neypotzli. Runs can start from the antechamber or a boss chamber.
 * Additional regions cover the wider dungeon for overlay / run tracking.
 */
final class NeypotzliRegions
{
	static final int ANTECHAMBER_REGION_ID = 6037;
	/**
	 * Note: world tiles around the Lunar Chest (e.g. 1513,9589) are also in region 6037.
	 * Do not treat "entered 6037 / antechamber run-start" as leaving the chest room.
	 */
	static final int ANCIENT_PRISON_REGION_ID = 5525;
	static final int EARTHBOUND_SOUTH_REGION_ID = 5782;
	static final int EARTHBOUND_NORTH_REGION_ID = 5783;

	/**
	 * Cam Torum city shares this region ID with the southern edge of Earthbound Cavern
	 * (NW door from the antechamber). Treat as dungeon only when another confirmed
	 * Neypotzli region is loaded in the scene.
	 */
	static final int CAM_TORUM_REGION_ID = 5781;

	// Eclipse Moon chamber only. Blue and Blood chambers share region IDs with
	// preparation caverns, so those are detected via boss NPC presence instead.
	private static final Set<Integer> BOSS_CHAMBER_REGION_IDS = new HashSet<>(Arrays.asList(
		6038
	));

	/** Regions that are always Neypotzli (never Cam Torum city alone). */
	private static final Set<Integer> NEYPOTZLI_REGION_IDS = new HashSet<>(Arrays.asList(
		// Ancient Prison / Blood Moon side
		5525, 5526, 5527,
		// Earthbound / Blue Moon prep corridors (NOT 5781 — ambiguous with Cam Torum)
		5782, 5783, 5784,
		// Antechamber / Eclipse / Streambound / shrine side
		6036, 6037, 6038, 6039, 6040, 6041, 6042, 6043, 6044
	));

	/**
	 * Prep campsite caverns where a new run should start after looting the chest.
	 * Excludes the Ancient Shrine / chest room and connecting corridors so walking
	 * from the Lunar Chest toward the next cavern does not reset mid-hallway.
	 */
	private static final Set<Integer> PREP_CAMPSITE_REGION_IDS = new HashSet<>(Arrays.asList(
		// Ancient Prison campsite
		5525, 5526, 5527,
		// Earthbound campsite
		5782, 5783, 5784,
		// Streambound campsite / fishing cavern (not shrine connectors)
		6039, 6040, 6042, 6043, 6044
	));

	/** Ancient Shrine / chest-side connectors — dungeon, but not a prep campsite. */
	private static final Set<Integer> SHRINE_REGION_IDS = new HashSet<>(Arrays.asList(
		6036, 6041
	));

	private NeypotzliRegions()
	{
	}

	static boolean isInAntechamber(Client client)
	{
		return isAntechamberRegion(getPlayerRegion(client));
	}

	static boolean isAntechamberRegion(int regionId)
	{
		return regionId == ANTECHAMBER_REGION_ID;
	}

	static boolean isInNeypotzli(Client client)
	{
		if (client == null || client.getLocalPlayer() == null)
		{
			return false;
		}

		int rawRegionId = getRawPlayerRegion(client);
		if (isNeypotzliRegion(rawRegionId))
		{
			return true;
		}

		int translatedRegionId = getPlayerRegion(client);
		if (isNeypotzliRegion(translatedRegionId))
		{
			return true;
		}

		// Earthbound's southern tiles share Cam Torum's region ID (5781).
		// Only count that region as dungeon when a confirmed Neypotzli region is loaded.
		if (rawRegionId == CAM_TORUM_REGION_ID || translatedRegionId == CAM_TORUM_REGION_ID)
		{
			return hasConfirmedDungeonRegionLoaded(client);
		}

		return false;
	}

	static boolean isNeypotzliRegion(int regionId)
	{
		return NEYPOTZLI_REGION_IDS.contains(regionId);
	}

	static boolean isInBossChamber(Client client)
	{
		return isBossChamberRegion(getPlayerRegion(client));
	}

	static boolean isBossChamberRegion(int regionId)
	{
		return BOSS_CHAMBER_REGION_IDS.contains(regionId);
	}

	static boolean isInRunStartArea(Client client)
	{
		return isRunStartRegion(getPlayerRegion(client));
	}

	static boolean isEffectiveRunStartArea(Client client, boolean bossPresent)
	{
		return isInRunStartArea(client) || (isInNeypotzli(client) && bossPresent);
	}

	static boolean isRunStartRegion(int regionId)
	{
		return isAntechamberRegion(regionId) || isBossChamberRegion(regionId);
	}

	static boolean isInPrepRoom(Client client, boolean bossPresent)
	{
		if (bossPresent || !isInNeypotzli(client))
		{
			return false;
		}

		return isPrepRoomRegion(getPlayerRegion(client), false)
			|| (getRawPlayerRegion(client) == CAM_TORUM_REGION_ID && hasConfirmedDungeonRegionLoaded(client));
	}

	static boolean isPrepRoomRegion(int regionId, boolean bossPresent)
	{
		if (!isNeypotzliRegion(regionId) || isRunStartRegion(regionId) || bossPresent)
		{
			return false;
		}

		return true;
	}

	/**
	 * True when standing in one of the three campsite caverns (Ancient Prison,
	 * Earthbound, Streambound), not the shrine/chest room or its connectors.
	 */
	static boolean isInPrepCampsite(Client client)
	{
		if (client == null || !isInNeypotzli(client))
		{
			return false;
		}

		int regionId = getPlayerRegion(client);
		if (isPrepCampsiteRegion(regionId))
		{
			return true;
		}

		// Earthbound's southern tiles share Cam Torum's region ID.
		return getRawPlayerRegion(client) == CAM_TORUM_REGION_ID
			&& hasConfirmedDungeonRegionLoaded(client);
	}

	static boolean isPrepCampsiteRegion(int regionId)
	{
		return PREP_CAMPSITE_REGION_IDS.contains(regionId);
	}

	static boolean isShrineRegion(int regionId)
	{
		return SHRINE_REGION_IDS.contains(regionId);
	}

	static boolean hasConfirmedDungeonRegionLoaded(Client client)
	{
		if (client == null)
		{
			return false;
		}

		int[] mapRegions = client.getMapRegions();
		if (mapRegions == null)
		{
			return false;
		}

		for (int mapRegion : mapRegions)
		{
			if (isNeypotzliRegion(mapRegion))
			{
				return true;
			}
		}

		return false;
	}

	static int getPlayerRegion(Client client)
	{
		WorldPoint location = getPlayerWorldPoint(client);
		return location == null ? -1 : location.getRegionID();
	}

	static WorldPoint getPlayerWorldPoint(Client client)
	{
		if (client == null || client.getLocalPlayer() == null)
		{
			return null;
		}

		WorldPoint raw = client.getLocalPlayer().getWorldLocation();
		if (raw != null && isNeypotzliRegion(raw.getRegionID()))
		{
			return raw;
		}

		LocalPoint localLocation = client.getLocalPlayer().getLocalLocation();
		if (localLocation == null)
		{
			return raw;
		}

		WorldPoint fromInstance = WorldPoint.fromLocalInstance(
			client,
			localLocation,
			raw == null ? 0 : raw.getPlane()
		);
		return fromInstance != null ? fromInstance : raw;
	}

	static int getRawPlayerRegion(Client client)
	{
		if (client == null || client.getLocalPlayer() == null)
		{
			return -1;
		}

		WorldPoint raw = client.getLocalPlayer().getWorldLocation();
		return raw == null ? -1 : raw.getRegionID();
	}
}

package com.perilousmoonssplits;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class PerilousMoonsPermutationOverlay extends OverlayPanel
{
	private final Client client;
	private final PerilousMoonsSplitsConfig config;
	private final PersonalBestStore personalBestStore;
	private final RunTracker runTracker;

	@Inject
	private PerilousMoonsPermutationOverlay(
		Client client,
		PerilousMoonsSplitsConfig config,
		PersonalBestStore personalBestStore,
		RunTracker runTracker)
	{
		this.client = client;
		this.config = config;
		this.personalBestStore = personalBestStore;
		this.runTracker = runTracker;
		setPosition(OverlayPosition.TOP_RIGHT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showRoutePersonalBests() || !runTracker.shouldShowOverlay(client))
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.setPreferredSize(new Dimension(config.permutationOverlayWidth(), 0));
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Route Total PBs")
			.color(Color.ORANGE)
			.build());

		for (List<MoonsBoss> route : MoonsBoss.allRoutes())
		{
			Long personalBest = personalBestStore.getPersonalBest(PersonalBestStore.totalKey(route));
			panelComponent.getChildren().add(LineComponent.builder()
				.left(MoonsBoss.formatRoute(route))
				.right(personalBest == null ? "--:--" : SplitData.formatDuration(personalBest))
				.leftColor(Color.LIGHT_GRAY)
				.rightColor(personalBest == null ? Color.GRAY : Color.WHITE)
				.build());
		}

		return super.render(graphics);
	}
}

package com.perilousmoonssplits;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;

@ConfigGroup("perilous-moons-splits")
public interface PerilousMoonsSplitsConfig extends Config
{
	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Show the split timer overlay panel"
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSupplies",
		name = "Show supplies",
		description = "Show food and potion counts for each split"
	)
	default boolean showSupplies()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayWidth",
		name = "Overlay width",
		description = "Width of the overlay panel in pixels"
	)
	default int overlayWidth()
	{
		return 400;
	}

	@ConfigItem(
		keyName = "showRoutePersonalBests",
		name = "Show route PBs",
		description = "Show a second overlay listing total personal bests for every boss order"
	)
	default boolean showRoutePersonalBests()
	{
		return false;
	}

	@ConfigItem(
		keyName = "routePbKeybind",
		name = "Toggle route PBs",
		description = "Toggle the route personal best overlay. You can also right-click the split overlay."
	)
	default Keybind routePbKeybind()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "permutationOverlayWidth",
		name = "Route PB overlay width",
		description = "Width of the route personal best overlay panel in pixels"
	)
	default int permutationOverlayWidth()
	{
		return 360;
	}

	@ConfigItem(
		keyName = "notifyPersonalBest",
		name = "Notify on PB",
		description = "Send a chat message when you beat a personal best split"
	)
	default boolean notifyPersonalBest()
	{
		return true;
	}

	@ConfigItem(
		keyName = "restartCurrentSplitKeybind",
		name = "Restart current split",
		description = "Restart only the currently running split timer (food/potion counts for that split are also cleared)"
	)
	default Keybind restartCurrentSplitKeybind()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "resetPersonalBests",
		name = "Reset personal bests",
		description = "Reset all stored personal bests for this plugin",
		warning = "Are you sure you want to reset all personal bests?"
	)
	default boolean resetPersonalBests()
	{
		return false;
	}

	@ConfigItem(
		keyName = "debugMode",
		name = "Debug mode",
		description = "Log region and varbit changes to the developer console"
	)
	default boolean debugMode()
	{
		return false;
	}
}

package com.perilousmoonssplits;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class PerilousMoonsSplitsOverlay extends OverlayPanel
{
	private final Client client;
	private final PerilousMoonsSplitsConfig config;
	private final RunTracker runTracker;
	private final PersonalBestStore personalBestStore;

	@Inject
	private PerilousMoonsSplitsOverlay(
		Client client,
		PerilousMoonsSplitsConfig config,
		RunTracker runTracker,
		PersonalBestStore personalBestStore,
		PerilousMoonsSplitsPlugin plugin)
	{
		this.client = client;
		this.config = config;
		this.runTracker = runTracker;
		this.personalBestStore = personalBestStore;
		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Toggle", "Route PBs", e -> plugin.toggleRoutePersonalBests());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || !runTracker.shouldShowOverlay(client))
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.setPreferredSize(new Dimension(config.overlayWidth(), 0));

		String orderSummary = runTracker.getOrderSummary();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(orderSummary.isEmpty()
				? "Perilous Moons Splits"
				: "Perilous Moons Splits [" + orderSummary + "]")
			.color(Color.ORANGE)
			.build());

		long nowMs = runTracker.getTimerNowMs();
		int activeSplitIndex = runTracker.getActiveSplitIndex();
		boolean hasStartedSplit = false;

		for (int i = 0; i < runTracker.getSplits().length; i++)
		{
			SplitData split = runTracker.getSplits()[i];
			boolean isActive = i == activeSplitIndex;
			hasStartedSplit |= split.isActive() || split.isComplete();

			String timeText = split.isComplete()
				? SplitData.formatDuration(split.getElapsedMs(split.getEndTimeMs()))
				: split.isActive()
					? SplitData.formatDuration(split.getElapsedMs(nowMs))
					: "--:--";

			Long personalBest = runTracker.getPersonalBestForSplit(i, personalBestStore);
			String pbText = personalBest == null ? "--:--" : SplitData.formatDuration(personalBest);
			Color lineColor = isActive ? Color.GREEN : Color.WHITE;

			panelComponent.getChildren().add(LineComponent.builder()
				.left(runTracker.getSplitLabel(i))
				.right(timeText + "  PB " + pbText)
				.leftColor(lineColor)
				.rightColor(lineColor)
				.build());

			if (config.showSupplies() && RunTracker.isBossSplit(i) && (split.isActive() || split.isComplete()))
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("  Food / Potions")
					.right(split.getFoodUsed() + " / " + split.getPotionsUsed())
					.leftColor(Color.LIGHT_GRAY)
					.rightColor(Color.LIGHT_GRAY)
					.build());
			}
		}

		if (hasStartedSplit)
		{
			long totalMs = runTracker.getTotalElapsedMs(nowMs);
			Long totalPb = runTracker.getTotalPersonalBest(personalBestStore);
			String totalPbText = totalPb == null ? "--:--" : SplitData.formatDuration(totalPb);
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Total")
				.right(SplitData.formatDuration(totalMs) + "  PB " + totalPbText)
				.leftColor(Color.YELLOW)
				.rightColor(Color.YELLOW)
				.build());
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Route PBs")
			.right(config.showRoutePersonalBests() ? "Shown" : "Hidden")
			.leftColor(Color.CYAN)
			.rightColor(Color.CYAN)
			.build());

		return super.render(graphics);
	}
}

package com.perilousmoonssplits;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.event.KeyEvent;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;

@Slf4j
@PluginDescriptor(name = "Perilous Moons Splits")
public class PerilousMoonsSplitsPlugin extends Plugin implements KeyListener
{
	private static final String CONFIG_GROUP = "perilous-moons-splits";

	@Inject private Client client;
	@Inject private PerilousMoonsSplitsConfig config;
	@Inject private OverlayManager overlayManager;
	@Inject private PerilousMoonsSplitsOverlay overlay;
	@Inject private PerilousMoonsPermutationOverlay permutationOverlay;
	@Inject private RunTracker runTracker;
	@Inject private PersonalBestStore personalBestStore;
	@Inject private KeyManager keyManager;
	@Inject private ConfigManager configManager;

	private int previousDeadBossCount = -1;
	private int previousRegionId = -1;
	private boolean previousInRunStartArea;
	private boolean previousInPrepRoom;
	private GameState previousGameState;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(permutationOverlay);
		keyManager.registerKeyListener(this);
		personalBestStore.load();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(permutationOverlay);
		keyManager.unregisterKeyListener(this);
		runTracker.manualReset();
	}

	@Override
	public void keyTyped(KeyEvent event)
	{
	}

	@Override
	public void keyPressed(KeyEvent event)
	{
		if (config.restartCurrentSplitKeybind().matches(event))
		{
			if (runTracker.restartCurrentSplit(System.currentTimeMillis()))
			{
				chat(
					"Perilous Moons Splits: restarted " + runTracker.getSplitLabel(runTracker.getActiveSplitIndex()) + ".",
					Color.ORANGE
				);
			}
		}
		else if (config.routePbKeybind().matches(event))
		{
			toggleRoutePersonalBests();
		}
	}

	@Override
	public void keyReleased(KeyEvent event)
	{
	}

	void toggleRoutePersonalBests()
	{
		boolean enabled = !config.showRoutePersonalBests();
		configManager.setConfiguration(CONFIG_GROUP, "showRoutePersonalBests", enabled);
		chat("Perilous Moons route PB overlay " + (enabled ? "shown" : "hidden") + ".", Color.ORANGE);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (MoonsBoss.fromNpcId(event.getNpc().getId()) != null)
		{
			runTracker.onBossNpcSpawned();
			runTracker.onBossPresenceChanged(client);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		if (MoonsBoss.fromNpcId(event.getNpc().getId()) != null)
		{
			runTracker.onBossNpcDespawned();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gameState = event.getGameState();
		if (gameState == GameState.LOGIN_SCREEN
			|| gameState == GameState.LOGGING_IN
			|| gameState == GameState.HOPPING
			|| gameState == GameState.CONNECTION_LOST)
		{
			runTracker.onLoggedOut();
		}
		else if (gameState == GameState.LOGGED_IN)
		{
			boolean fromLoginOrHop = previousGameState == GameState.LOGIN_SCREEN
				|| previousGameState == GameState.LOGGING_IN
				|| previousGameState == GameState.HOPPING
				|| previousGameState == GameState.CONNECTION_LOST;

			previousDeadBossCount = -1;
			previousRegionId = -1;
			previousInRunStartArea = false;
			previousInPrepRoom = false;
			runTracker.onLoggedIn(fromLoginOrHop);
			if (config.debugMode())
			{
				log.debug("Logged in (fromLoginOrHop={}) - region tracking reset", fromLoginOrHop);
			}
		}
		previousGameState = gameState;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (config.debugMode())
		{
			logRegionState();
		}

		runTracker.onOverlayRegionChanged(client);
		runTracker.onRegionChanged(client);
		long nowMs = runTracker.getTimerNowMs();
		handleCompletedPrepSplit(runTracker.syncBossCombatState(client, nowMs), "tick");

		int deadBossCount = RunTracker.getDeadBossCount(client);
		if (previousDeadBossCount < 0)
		{
			previousDeadBossCount = deadBossCount;
			return;
		}

		if (deadBossCount == 0 && previousDeadBossCount > 0)
		{
			if (config.debugMode())
			{
				log.debug("Boss death varbits reset - chest looted, waiting for next room");
			}
			runTracker.onChestLooted(client);
		}
		previousDeadBossCount = deadBossCount;
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor actor = event.getActor();
		if (actor == client.getLocalPlayer())
		{
			runTracker.onPlayerDied();
			return;
		}
		if (!(actor instanceof NPC))
		{
			return;
		}

		MoonsBoss boss = MoonsBoss.fromNpcId(((NPC) actor).getId());
		if (boss != null)
		{
			handleBossKill(boss, "npc-death");
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varbitId = event.getVarbitId();
		if (varbitId == VarbitID.PMOON_BOSS_IN_COMBAT)
		{
			if (config.debugMode())
			{
				log.debug("PMOON_BOSS_IN_COMBAT={}", event.getValue());
			}
			handleCompletedPrepSplit(runTracker.syncBossCombatState(client, System.currentTimeMillis()), "varbit");
			return;
		}

		MoonsBoss boss = MoonsBoss.fromDeathVarbit(varbitId);
		if (boss != null && event.getValue() == 1)
		{
			handleBossKill(boss, "varbit");
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.PMOON_REWARD)
		{
			if (config.debugMode())
			{
				log.debug("Lunar chest reward interface opened - waiting for next room before starting next run");
			}
			runTracker.onChestLooted(client);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if ("Eat".equals(option) || "Drink".equals(option))
		{
			runTracker.onEatOrDrink(option);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()) || !"resetPersonalBests".equals(event.getKey()))
		{
			return;
		}
		if (!config.resetPersonalBests())
		{
			return;
		}

		personalBestStore.clearAll();
		configManager.setConfiguration(CONFIG_GROUP, "resetPersonalBests", "false");
		chat("Perilous Moons personal bests reset.", Color.ORANGE);
	}

	@Provides
	PerilousMoonsSplitsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PerilousMoonsSplitsConfig.class);
	}

	private void handleBossKill(MoonsBoss boss, String source)
	{
		if (config.debugMode())
		{
			log.debug("Boss kill detected via {}: {}", source, boss);
		}

		int bossNumber = runTracker.getKillOrder().size();
		int completedSplitIndex = RunTracker.bossSplitIndex(bossNumber + 1);
		long durationMs = runTracker.onBossKilled(boss, System.currentTimeMillis());
		if (durationMs < 0)
		{
			return;
		}

		handlePersonalBest(completedSplitIndex, durationMs);
		if (runTracker.isRunComplete())
		{
			handleTotalPersonalBest();
		}
	}

	private void handleCompletedPrepSplit(int completedPrepIndex, String source)
	{
		if (completedPrepIndex < 0 || !RunTracker.isPrepSplit(completedPrepIndex))
		{
			return;
		}

		SplitData prepSplit = runTracker.getSplits()[completedPrepIndex];
		if (!prepSplit.isComplete())
		{
			return;
		}

		if (config.debugMode())
		{
			log.debug("Boss combat started via {} after {}", source, runTracker.getSplitLabel(completedPrepIndex));
		}
		handlePersonalBest(completedPrepIndex, prepSplit.getElapsedMs(prepSplit.getEndTimeMs()));
	}

	private void handlePersonalBest(int completedSplitIndex, long durationMs)
	{
		String pbKey = runTracker.getPersonalBestKey(completedSplitIndex);
		if (pbKey == null)
		{
			return;
		}

		if (personalBestStore.updatePersonalBest(pbKey, durationMs) && config.notifyPersonalBest())
		{
			chat(String.format(
				"Perilous Moons %s PB: %s",
				runTracker.getSplitLabel(completedSplitIndex),
				SplitData.formatDuration(durationMs)), Color.GREEN);
		}
	}

	private void handleTotalPersonalBest()
	{
		List<MoonsBoss> route = runTracker.getRouteOrder();
		if (route.size() < 3)
		{
			return;
		}

		long totalMs = runTracker.getTotalElapsedMs(System.currentTimeMillis());
		if (personalBestStore.updatePersonalBest(PersonalBestStore.totalKey(route), totalMs) && config.notifyPersonalBest())
		{
			chat("Perilous Moons Total PB: " + SplitData.formatDuration(totalMs), Color.GREEN);
		}
	}

	private void chat(String message, Color color)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", ColorUtil.wrapWithColorTag(message, color), null);
	}

	private void logRegionState()
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}

		int rawRegionId = NeypotzliRegions.getRawPlayerRegion(client);
		int regionId = NeypotzliRegions.getPlayerRegion(client);
		boolean inRunStartArea = NeypotzliRegions.isEffectiveRunStartArea(client, runTracker.isBossPresent());
		boolean inPrepRoom = NeypotzliRegions.isInPrepRoom(client, runTracker.isBossPresent());
		if (regionId == previousRegionId
			&& rawRegionId == previousRegionId
			&& inRunStartArea == previousInRunStartArea
			&& inPrepRoom == previousInPrepRoom)
		{
			return;
		}

		log.debug(
			"Region raw={} translated={} (neypotzli={}, antechamber={}, bossChamber={}, prepRoom={}, bossPresent={}, startArea={}, canStart={}, overlay={}, runActive={}, runComplete={}, awaitingNext={})",
			rawRegionId,
			regionId,
			NeypotzliRegions.isInNeypotzli(client),
			NeypotzliRegions.isInAntechamber(client),
			NeypotzliRegions.isInBossChamber(client),
			inPrepRoom,
			runTracker.isBossPresent(),
			inRunStartArea,
			RunTracker.canStartRunHere(inRunStartArea, inPrepRoom),
			runTracker.shouldShowOverlay(client),
			runTracker.isRunActive(),
			runTracker.isRunComplete(),
			runTracker.isAwaitingNextRun()
		);
		previousRegionId = rawRegionId != -1 ? rawRegionId : regionId;
		previousInRunStartArea = inRunStartArea;
		previousInPrepRoom = inPrepRoom;
	}
}

package com.perilousmoonssplits;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
class PersonalBestStore
{
	private static final String CONFIG_GROUP = "perilous-moons-splits";
	private static final String PB_CONFIG_KEY = "personalBestsJson";

	private final ConfigManager configManager;
	private final Gson gson;
	private final Map<String, Long> personalBests = new HashMap<>();

	@Inject
	PersonalBestStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
		load();
	}

	void load()
	{
		personalBests.clear();
		String json = configManager.getConfiguration(CONFIG_GROUP, PB_CONFIG_KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		JsonObject loaded = gson.fromJson(json, JsonObject.class);
		if (loaded == null)
		{
			return;
		}

		for (Map.Entry<String, JsonElement> entry : loaded.entrySet())
		{
			if (entry.getValue().isJsonPrimitive())
			{
				personalBests.put(entry.getKey(), entry.getValue().getAsLong());
			}
		}
	}

	Long getPersonalBest(String key)
	{
		return personalBests.get(key);
	}

	boolean updatePersonalBest(String key, long durationMs)
	{
		Long existing = personalBests.get(key);
		if (existing != null && durationMs >= existing)
		{
			return false;
		}

		personalBests.put(key, durationMs);
		save();
		return true;
	}

	void clearAll()
	{
		personalBests.clear();
		save();
	}

	private void save()
	{
		configManager.setConfiguration(CONFIG_GROUP, PB_CONFIG_KEY, gson.toJson(personalBests));
	}

	static String prep1Key(MoonsBoss firstBoss)
	{
		return "prep1." + firstBoss.name();
	}

	static String prep2Key(MoonsBoss firstBoss, MoonsBoss secondBoss)
	{
		return "prep2." + firstBoss.name() + ">" + secondBoss.name();
	}

	static String prep3Key(List<MoonsBoss> order)
	{
		return "prep3." + formatOrder(order);
	}

	static String split1Key(MoonsBoss firstBoss)
	{
		return "split1." + firstBoss.name();
	}

	static String split2Key(MoonsBoss firstBoss, MoonsBoss secondBoss)
	{
		return "split2." + firstBoss.name() + ">" + secondBoss.name();
	}

	static String split3Key(List<MoonsBoss> order)
	{
		return "split3." + formatOrder(order);
	}

	static String totalKey(List<MoonsBoss> order)
	{
		return "total." + formatOrder(order);
	}

	private static String formatOrder(List<MoonsBoss> order)
	{
		StringBuilder builder = new StringBuilder();
		for (int i = 0; i < order.size(); i++)
		{
			if (i > 0)
			{
				builder.append('>');
			}
			builder.append(order.get(i).name());
		}
		return builder.toString();
	}
}

package com.perilousmoonssplits;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;

@Singleton
public class RunTracker
{
	static final int SPLIT_COUNT = 6;
	/** Minimum tiles moved from the chest before the next run can start in the same region. */
	static final int CHEST_LEAVE_DISTANCE = 10;

	@Getter
	private final List<MoonsBoss> killOrder = new ArrayList<>();

	/** Boss order from the previous completed run, used to show PBs before kills are confirmed. */
	private final List<MoonsBoss> assumedOrder = new ArrayList<>();

	@Getter
	private final SplitData[] splits = new SplitData[] {
		new SplitData(0),
		new SplitData(1),
		new SplitData(2),
		new SplitData(3),
		new SplitData(4),
		new SplitData(5)
	};

	private boolean runActive;
	private boolean runComplete;
	private boolean wasInNeypotzli;
	private boolean wasInRunStartArea;
	private boolean wasInPrepRoom;
	private boolean wasBossInCombat;
	private boolean awaitingNextRun;
	private int lootRegionId = -1;
	private WorldPoint lootLocation;
	private int visibleBossCount;
	private boolean overlaySuppressedUntilReenter;
	/** When set, active split clocks are frozen at this wall-clock time (logout / hop). */
	private long timerPausedAtMs = -1;

	public boolean isRunActive()
	{
		return runActive;
	}

	public boolean isRunComplete()
	{
		return runComplete;
	}

	public boolean hasRunResults()
	{
		return runActive || runComplete || !killOrder.isEmpty();
	}

	public int getActiveSplitIndex()
	{
		for (int i = 0; i < splits.length; i++)
		{
			if (splits[i].isActive())
			{
				return i;
			}
		}
		return -1;
	}

	static boolean isPrepSplit(int splitIndex)
	{
		return splitIndex >= 0 && splitIndex < SPLIT_COUNT && splitIndex % 2 == 0;
	}

	static boolean isBossSplit(int splitIndex)
	{
		return splitIndex >= 0 && splitIndex < SPLIT_COUNT && splitIndex % 2 == 1;
	}

	static int prepNumberFromSplit(int splitIndex)
	{
		return splitIndex / 2 + 1;
	}

	static int bossNumberFromSplit(int splitIndex)
	{
		return splitIndex / 2 + 1;
	}

	static int prepSplitIndex(int prepNumber)
	{
		return (prepNumber - 1) * 2;
	}

	static int bossSplitIndex(int bossNumber)
	{
		return bossNumber * 2 - 1;
	}

	public void onRegionChanged(Client client)
	{
		boolean inNeypotzli = NeypotzliRegions.isInNeypotzli(client);
		boolean inRunStartArea = NeypotzliRegions.isEffectiveRunStartArea(client, isBossPresent());
		boolean inPrepRoom = NeypotzliRegions.isInPrepRoom(client, isBossPresent());
		boolean canStartHere = canStartRunHere(inRunStartArea, inPrepRoom);
		int regionId = NeypotzliRegions.getPlayerRegion(client);

		if (awaitingNextRun && shouldStartAfterChestLoot(client, inNeypotzli, regionId))
		{
			startNextRun(client, System.currentTimeMillis());
		}
		else if (!awaitingNextRun)
		{
			if (!wasInNeypotzli && inNeypotzli)
			{
				tryStartRun(client, canStartHere);
			}

			if ((!wasInRunStartArea && inRunStartArea) || (!wasInPrepRoom && inPrepRoom))
			{
				tryStartRun(client, true);
			}
		}

		wasInNeypotzli = inNeypotzli;
		wasInRunStartArea = inRunStartArea;
		wasInPrepRoom = inPrepRoom;
	}

	public void onLoggedIn(boolean fromLoginOrHop)
	{
		wasInNeypotzli = false;
		wasInRunStartArea = false;
		wasInPrepRoom = false;
		wasBossInCombat = false;
		visibleBossCount = 0;

		// Always resume if paused. Login/hop often goes LOGGING_IN/HOPPING -> LOADING ->
		// LOGGED_IN, so previousGameState may be LOADING and fromLoginOrHop is false.
		resumeTimers(System.currentTimeMillis());

		if (fromLoginOrHop)
		{
			overlaySuppressedUntilReenter = false;
		}

		// Only clear completed-run display on a real login/hop. Moons teleports after a
		// boss kill can also emit LOGGED_IN via LOADING, and must keep the finished times.
		if (fromLoginOrHop && runComplete && !awaitingNextRun)
		{
			runActive = false;
			runComplete = false;
			killOrder.clear();
			for (SplitData split : splits)
			{
				split.reset();
			}
		}
	}

	void onLoggedOut()
	{
		pauseTimers(System.currentTimeMillis());
	}

	/**
	 * Wall-clock "now" for displaying / advancing active splits. Frozen while logged out.
	 */
	long getTimerNowMs()
	{
		return timerPausedAtMs >= 0 ? timerPausedAtMs : System.currentTimeMillis();
	}

	boolean isTimerPaused()
	{
		return timerPausedAtMs >= 0;
	}

	void pauseTimers(long nowMs)
	{
		if (timerPausedAtMs >= 0 || !runActive)
		{
			return;
		}
		timerPausedAtMs = nowMs;
	}

	void resumeTimers(long nowMs)
	{
		if (timerPausedAtMs < 0)
		{
			return;
		}

		long pausedForMs = Math.max(0, nowMs - timerPausedAtMs);
		if (pausedForMs > 0)
		{
			for (SplitData split : splits)
			{
				if (split.isActive())
				{
					split.shiftStart(pausedForMs);
				}
			}
		}
		timerPausedAtMs = -1;
	}

	boolean shouldShowOverlay(Client client)
	{
		if (overlaySuppressedUntilReenter)
		{
			return false;
		}
		if (client == null || client.getLocalPlayer() == null)
		{
			return false;
		}
		// Region only — boss combat varbits / NPC counts can stick after leaving the dungeon.
		return NeypotzliRegions.isInNeypotzli(client);
	}

	boolean shouldShowOverlayForRegion(int regionId)
	{
		return NeypotzliRegions.isNeypotzliRegion(regionId) && !overlaySuppressedUntilReenter;
	}

	void onPlayerDied()
	{
		overlaySuppressedUntilReenter = true;
	}

	void onOverlayRegionChanged(Client client)
	{
		if (!NeypotzliRegions.isInNeypotzli(client))
		{
			overlaySuppressedUntilReenter = false;
			visibleBossCount = 0;
		}
	}

	void onLeftDungeonRegion(int regionId)
	{
		if (!NeypotzliRegions.isNeypotzliRegion(regionId))
		{
			overlaySuppressedUntilReenter = false;
		}
	}

	public void onChestLooted(Client client)
	{
		// Only arm after a finished (or partially finished) run that is no longer active.
		if (runActive || killOrder.isEmpty())
		{
			return;
		}

		if (awaitingNextRun)
		{
			return;
		}

		awaitingNextRun = true;
		lootRegionId = NeypotzliRegions.getPlayerRegion(client);
		lootLocation = NeypotzliRegions.getPlayerWorldPoint(client);
		syncRegionState(client);
	}

	public void onBossNpcSpawned()
	{
		visibleBossCount++;
	}

	public void onBossPresenceChanged(Client client)
	{
		boolean inRunStartArea = NeypotzliRegions.isEffectiveRunStartArea(client, isBossPresent());
		boolean inPrepRoom = NeypotzliRegions.isInPrepRoom(client, isBossPresent());
		int regionId = NeypotzliRegions.getPlayerRegion(client);

		if (awaitingNextRun && shouldStartAfterChestLoot(
			client,
			NeypotzliRegions.isInNeypotzli(client),
			regionId))
		{
			startNextRun(client, System.currentTimeMillis());
		}
		else if (!awaitingNextRun
			&& ((!wasInRunStartArea && inRunStartArea) || (!wasInPrepRoom && inPrepRoom)))
		{
			tryStartRun(client, true);
		}
		wasInRunStartArea = inRunStartArea;
		wasInPrepRoom = inPrepRoom;
	}

	public void onBossNpcDespawned()
	{
		if (visibleBossCount > 0)
		{
			visibleBossCount--;
		}
	}

	boolean isBossPresent()
	{
		return visibleBossCount > 0;
	}

	/**
	 * @return completed prep split index, or -1 if no transition occurred
	 */
	public int syncBossCombatState(Client client, long nowMs)
	{
		if (!runActive || client == null)
		{
			return -1;
		}

		boolean inCombat = isBossInCombat(client);
		if (!wasBossInCombat && inCombat)
		{
			int completedPrepIndex = getActiveSplitIndex();
			if (onBossCombatStarted(nowMs) >= 0)
			{
				wasBossInCombat = inCombat;
				return completedPrepIndex;
			}
		}

		wasBossInCombat = inCombat;
		return -1;
	}

	/**
	 * @return duration of the completed prep split in milliseconds, or -1 if ignored
	 */
	public long onBossCombatStarted(long nowMs)
	{
		if (!runActive)
		{
			return -1;
		}

		int activeIndex = getActiveSplitIndex();
		if (!isPrepSplit(activeIndex) || !splits[activeIndex].isActive())
		{
			return -1;
		}

		SplitData prepSplit = splits[activeIndex];
		prepSplit.finish(nowMs);
		long durationMs = prepSplit.getElapsedMs(nowMs);
		startSplit(activeIndex + 1, nowMs);
		return durationMs;
	}

	/**
	 * @return duration of the completed boss split in milliseconds, or -1 if ignored
	 */
	public long onBossKilled(MoonsBoss boss, long nowMs)
	{
		if (!runActive || boss == null || killOrder.contains(boss))
		{
			return -1;
		}

		int bossNumber = killOrder.size() + 1;
		int splitIndex = bossSplitIndex(bossNumber);
		if (!assumedOrder.isEmpty() && killOrder.size() < assumedOrder.size()
			&& assumedOrder.get(killOrder.size()) != boss)
		{
			assumedOrder.clear();
		}
		if (splitIndex >= splits.length || getActiveSplitIndex() != splitIndex || !splits[splitIndex].isActive())
		{
			return -1;
		}

		SplitData split = splits[splitIndex];
		split.finish(nowMs);
		long durationMs = split.getElapsedMs(nowMs);
		killOrder.add(boss);

		if (killOrder.size() < 3)
		{
			startSplit(prepSplitIndex(killOrder.size() + 1), nowMs);
		}
		else
		{
			runActive = false;
			runComplete = true;
			assumedOrder.clear();
			assumedOrder.addAll(killOrder);
		}

		return durationMs;
	}

	public void onEatOrDrink(String action)
	{
		int activeIndex = getActiveSplitIndex();
		if (activeIndex < 0)
		{
			return;
		}

		if ("Eat".equals(action))
		{
			splits[activeIndex].incrementFood();
		}
		else if ("Drink".equals(action))
		{
			splits[activeIndex].incrementPotions();
		}
	}

	public void manualReset()
	{
		resetRun();
		wasInRunStartArea = false;
		wasInPrepRoom = false;
		awaitingNextRun = false;
		lootRegionId = -1;
		lootLocation = null;
	}

	/**
	 * Restarts only the currently active split timer and clears its food/potion counts.
	 * Completed splits and kill order are left unchanged.
	 *
	 * @return true if an active split was restarted
	 */
	public boolean restartCurrentSplit(long nowMs)
	{
		int activeIndex = getActiveSplitIndex();
		if (activeIndex < 0 || !runActive)
		{
			return false;
		}

		if (timerPausedAtMs >= 0)
		{
			timerPausedAtMs = nowMs;
		}

		splits[activeIndex].start(nowMs);
		return true;
	}

	void beginRun(long nowMs)
	{
		awaitingNextRun = false;
		lootRegionId = -1;
		lootLocation = null;
		timerPausedAtMs = -1;
		runActive = true;
		runComplete = false;
		wasBossInCombat = false;
		killOrder.clear();
		for (SplitData split : splits)
		{
			split.reset();
		}
		startSplit(0, nowMs);
	}

	public String getSplitLabel(int splitIndex)
	{
		MoonsBoss first = getBossAt(0);
		MoonsBoss second = getBossAt(1);
		MoonsBoss third = getBossAt(2);

		switch (splitIndex)
		{
			case 0:
				return formatPrepLabel(1);
			case 1:
				return first != null ? first.getShortName() : "Boss 1";
			case 2:
				return formatPrepLabel(2);
			case 3:
				return second != null ? second.getShortName() : "Boss 2";
			case 4:
				return formatPrepLabel(3);
			case 5:
				return third != null ? third.getShortName() : "Boss 3";
			default:
				return "";
		}
	}

	public String getOrderSummary()
	{
		List<MoonsBoss> displayOrder = getDisplayOrder();
		if (displayOrder.isEmpty())
		{
			return "";
		}

		String summary = formatOrderSummary(displayOrder);
		if (isAssumedOrderApplicable() && killOrder.size() < 3)
		{
			return summary + " (assumed)";
		}

		return summary;
	}

	public long getTotalElapsedMs(long nowMs)
	{
		long total = 0;
		for (SplitData split : splits)
		{
			if (split.isComplete())
			{
				total += split.getElapsedMs(split.getEndTimeMs());
			}
			else if (split.isActive())
			{
				total += split.getElapsedMs(nowMs);
			}
		}
		return total;
	}

	public Long getTotalPersonalBest(PersonalBestStore store)
	{
		List<MoonsBoss> route = getRouteOrder();
		if (route.size() < 3)
		{
			return null;
		}
		return store.getPersonalBest(PersonalBestStore.totalKey(route));
	}

	List<MoonsBoss> getRouteOrder()
	{
		List<MoonsBoss> displayOrder = getDisplayOrder();
		if (displayOrder.size() == 3)
		{
			return displayOrder;
		}
		return killOrder;
	}

	public Long getPersonalBestForSplit(int splitIndex, PersonalBestStore store)
	{
		String key = getPersonalBestKey(splitIndex);
		return key == null ? null : store.getPersonalBest(key);
	}

	String getPersonalBestKey(int splitIndex)
	{
		MoonsBoss first = getBossAt(0);
		MoonsBoss second = getBossAt(1);
		MoonsBoss third = getBossAt(2);

		if (isPrepSplit(splitIndex))
		{
			switch (prepNumberFromSplit(splitIndex))
			{
				case 1:
					return first == null ? null : PersonalBestStore.prep1Key(first);
				case 2:
					return first == null || second == null ? null : PersonalBestStore.prep2Key(first, second);
				case 3:
					return first == null || second == null || third == null
						? null
						: PersonalBestStore.prep3Key(Arrays.asList(first, second, third));
				default:
					return null;
			}
		}

		if (isBossSplit(splitIndex))
		{
			switch (bossNumberFromSplit(splitIndex))
			{
				case 1:
					return first == null ? null : PersonalBestStore.split1Key(first);
				case 2:
					return first == null || second == null ? null : PersonalBestStore.split2Key(first, second);
				case 3:
					return first == null || second == null || third == null
						? null
						: PersonalBestStore.split3Key(Arrays.asList(first, second, third));
				default:
					return null;
			}
		}

		return null;
	}

	static int getDeadBossCount(Client client)
	{
		int dead = 0;
		if (client.getVarbitValue(VarbitID.PMOON_BOSS_BLOOD_DEAD) == 1)
		{
			dead++;
		}
		if (client.getVarbitValue(VarbitID.PMOON_BOSS_BLUE_DEAD) == 1)
		{
			dead++;
		}
		if (client.getVarbitValue(VarbitID.PMOON_BOSS_ECLIPSE_DEAD) == 1)
		{
			dead++;
		}
		return dead;
	}

	static boolean isBossInCombat(Client client)
	{
		return client.getVarbitValue(VarbitID.PMOON_BOSS_IN_COMBAT) == 1;
	}

	private boolean shouldStartAfterChestLoot(
		Client client,
		boolean inNeypotzli,
		int regionId)
	{
		if (!inNeypotzli)
		{
			return false;
		}

		boolean inPrepCampsite = NeypotzliRegions.isInPrepCampsite(client);
		boolean leftChestRegion = regionId != -1 && lootRegionId != -1 && regionId != lootRegionId;

		return shouldStartNextRunAfterChest(
			inNeypotzli,
			inPrepCampsite,
			leftChestRegion,
			hasLeftChestArea(client)
		);
	}

	/**
	 * After looting, only start the next run once the player is in a prep campsite
	 * cavern (Ancient Prison / Earthbound / Streambound).
	 * <p>
	 * Region 6037 includes the Lunar Chest / shrine area, so antechamber / "run start"
	 * and distance-from-chest alone must not start the next run while still in that room.
	 */
	static boolean shouldStartNextRunAfterChest(
		boolean inNeypotzli,
		boolean inPrepCampsite,
		boolean leftChestRegion,
		boolean leftChestAreaByDistance)
	{
		if (!inNeypotzli || !inPrepCampsite)
		{
			return false;
		}

		// Prefer a real transition into a campsite region away from the chest.
		if (leftChestRegion)
		{
			return true;
		}

		// Same-region fallback only if the campsite somehow shares the chest region.
		return leftChestAreaByDistance;
	}

	private boolean hasLeftChestArea(Client client)
	{
		if (lootLocation == null || client == null)
		{
			return false;
		}

		WorldPoint current = NeypotzliRegions.getPlayerWorldPoint(client);
		return current != null && current.distanceTo(lootLocation) >= CHEST_LEAVE_DISTANCE;
	}

	void startNextRunAfterChestLoot(long nowMs)
	{
		if (awaitingNextRun)
		{
			startNextRun(null, nowMs);
		}
	}

	private void startNextRun(Client client, long nowMs)
	{
		beginRun(nowMs);
		if (client != null && isBossInCombat(client))
		{
			wasBossInCombat = true;
			onBossCombatStarted(nowMs);
		}
	}

	static boolean canStartRunHere(boolean inRunStartArea, boolean inPrepRoom)
	{
		return inRunStartArea || inPrepRoom;
	}

	boolean isAwaitingNextRun()
	{
		return awaitingNextRun;
	}

	private void tryStartRun(Client client, boolean canStartHere)
	{
		if (awaitingNextRun || runActive || runComplete || !canStartHere || getDeadBossCount(client) != 0)
		{
			return;
		}

		long nowMs = System.currentTimeMillis();
		beginRun(nowMs);
		if (isBossInCombat(client))
		{
			wasBossInCombat = true;
			onBossCombatStarted(nowMs);
		}
	}

	private void startSplit(int splitIndex, long nowMs)
	{
		splits[splitIndex].start(nowMs);
	}

	private void resetRun()
	{
		runActive = false;
		runComplete = false;
		wasBossInCombat = false;
		awaitingNextRun = false;
		timerPausedAtMs = -1;
		lootRegionId = -1;
		lootLocation = null;
		killOrder.clear();
		for (SplitData split : splits)
		{
			split.reset();
		}
	}

	private void syncRegionState(Client client)
	{
		if (client == null)
		{
			wasInNeypotzli = false;
			wasInRunStartArea = false;
			wasInPrepRoom = false;
			return;
		}

		wasInNeypotzli = NeypotzliRegions.isInNeypotzli(client);
		wasInRunStartArea = NeypotzliRegions.isEffectiveRunStartArea(client, isBossPresent());
		wasInPrepRoom = NeypotzliRegions.isInPrepRoom(client, isBossPresent());
	}

	MoonsBoss getBossAt(int index)
	{
		if (index < killOrder.size())
		{
			return killOrder.get(index);
		}

		if (isAssumedOrderApplicable() && index < assumedOrder.size())
		{
			return assumedOrder.get(index);
		}

		return null;
	}

	boolean isAssumedOrderApplicable()
	{
		if (assumedOrder.isEmpty())
		{
			return false;
		}

		if (killOrder.size() > assumedOrder.size())
		{
			return false;
		}

		for (int i = 0; i < killOrder.size(); i++)
		{
			if (killOrder.get(i) != assumedOrder.get(i))
			{
				return false;
			}
		}

		return true;
	}

	void seedAssumedOrderForTest(List<MoonsBoss> order)
	{
		assumedOrder.clear();
		assumedOrder.addAll(order);
	}

	private static String formatPrepLabel(int prepNumber)
	{
		return "Prep " + prepNumber;
	}

	private List<MoonsBoss> getDisplayOrder()
	{
		if (isAssumedOrderApplicable())
		{
			return new ArrayList<>(assumedOrder);
		}
		return new ArrayList<>(killOrder);
	}

	private static String formatOrderSummary(List<MoonsBoss> order)
	{
		StringBuilder builder = new StringBuilder();
		for (int i = 0; i < order.size(); i++)
		{
			if (i > 0)
			{
				builder.append(" -> ");
			}
			builder.append(order.get(i).getShortName());
		}
		return builder.toString();
	}
}

package com.perilousmoonssplits;

import lombok.Getter;
import lombok.Setter;

@Getter
class SplitData
{
	private final int index;
	private long startTimeMs = -1;
	@Setter
	private long endTimeMs = -1;
	private int foodUsed;
	private int potionsUsed;

	SplitData(int index)
	{
		this.index = index;
	}

	void start(long nowMs)
	{
		startTimeMs = nowMs;
		endTimeMs = -1;
		foodUsed = 0;
		potionsUsed = 0;
	}

	void finish(long nowMs)
	{
		endTimeMs = nowMs;
	}

	void incrementFood()
	{
		foodUsed++;
	}

	void incrementPotions()
	{
		potionsUsed++;
	}

	long getElapsedMs(long nowMs)
	{
		if (startTimeMs < 0)
		{
			return -1;
		}
		long end = endTimeMs >= 0 ? endTimeMs : nowMs;
		return end - startTimeMs;
	}

	boolean isActive()
	{
		return startTimeMs >= 0 && endTimeMs < 0;
	}

	boolean isComplete()
	{
		return startTimeMs >= 0 && endTimeMs >= 0;
	}

	void reset()
	{
		startTimeMs = -1;
		endTimeMs = -1;
		foodUsed = 0;
		potionsUsed = 0;
	}

	/** Move an active split's start forward so logout time is excluded from elapsed. */
	void shiftStart(long deltaMs)
	{
		if (startTimeMs >= 0 && endTimeMs < 0 && deltaMs > 0)
		{
			startTimeMs += deltaMs;
		}
	}

	static String formatDuration(long millis)
	{
		if (millis < 0)
		{
			return "--:--";
		}

		long totalCentiseconds = millis / 10;
		long centiseconds = totalCentiseconds % 100;
		long totalSeconds = totalCentiseconds / 100;
		long seconds = totalSeconds % 60;
		long minutes = totalSeconds / 60;
		return String.format("%d:%02d.%d", minutes, seconds, centiseconds / 10);
	}
}

package com.perilousmoonssplits;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class DungeonOverlayVisibilityTest
{
	@Test
	public void overlayHiddenOutsideDungeon()
	{
		RunTracker tracker = new RunTracker();
		assertFalse(tracker.shouldShowOverlayForRegion(3200));
	}

	@Test
	public void overlayShownInsideDungeon()
	{
		RunTracker tracker = new RunTracker();
		assertTrue(tracker.shouldShowOverlayForRegion(NeypotzliRegions.ANTECHAMBER_REGION_ID));
	}

	@Test
	public void earthboundCavernIsNeypotzli()
	{
		assertTrue(NeypotzliRegions.isNeypotzliRegion(5782));
		assertTrue(NeypotzliRegions.isNeypotzliRegion(5783));
		assertTrue(NeypotzliRegions.isNeypotzliRegion(5784));
		assertTrue(NeypotzliRegions.isPrepRoomRegion(5782, false));
	}

	@Test
	public void playerDeathHidesOverlayUntilReenter()
	{
		RunTracker tracker = new RunTracker();
		assertTrue(tracker.shouldShowOverlayForRegion(NeypotzliRegions.ANTECHAMBER_REGION_ID));

		tracker.onPlayerDied();
		assertFalse(tracker.shouldShowOverlayForRegion(NeypotzliRegions.ANTECHAMBER_REGION_ID));
		assertFalse(tracker.shouldShowOverlayForRegion(NeypotzliRegions.ANCIENT_PRISON_REGION_ID));
		assertFalse(tracker.shouldShowOverlayForRegion(5782));

		tracker.onLeftDungeonRegion(3200);
		assertFalse(tracker.shouldShowOverlayForRegion(3200));

		assertTrue(tracker.shouldShowOverlayForRegion(NeypotzliRegions.ANTECHAMBER_REGION_ID));
		assertTrue(tracker.shouldShowOverlayForRegion(NeypotzliRegions.ANCIENT_PRISON_REGION_ID));
		assertTrue(tracker.shouldShowOverlayForRegion(5782));
	}

	@Test
	public void overlayRequiresDungeonRegionNotCombatFallback()
	{
		RunTracker tracker = new RunTracker();
		assertFalse(tracker.shouldShowOverlayForRegion(3200));
		assertTrue(tracker.shouldShowOverlayForRegion(NeypotzliRegions.ANTECHAMBER_REGION_ID));
	}

	@Test
	public void overlayHiddenInCamTorumRegion()
	{
		RunTracker tracker = new RunTracker();
		assertFalse(tracker.shouldShowOverlayForRegion(NeypotzliRegions.CAM_TORUM_REGION_ID));
		assertTrue(tracker.shouldShowOverlayForRegion(NeypotzliRegions.ANTECHAMBER_REGION_ID));
	}

	@Test
	public void realLoginClearsDeathSuppression()
	{
		RunTracker tracker = new RunTracker();
		tracker.onPlayerDied();
		assertFalse(tracker.shouldShowOverlayForRegion(5782));

		tracker.onLoggedIn(false);
		assertFalse(tracker.shouldShowOverlayForRegion(5782));

		tracker.onLoggedIn(true);
		assertTrue(tracker.shouldShowOverlayForRegion(5782));
	}
}

